"""
Sliding-window rate limiter middleware for POST /api/chat/* endpoints.

Config (env vars):
  RATE_LIMIT_RPM   — max requests per 60-second window per client IP (default: 10)

Returns HTTP 429 {"error": "rate_limit_exceeded", "retry_after": <seconds>}
when the limit is exceeded. All other routes are unaffected.
"""

import collections
import json
import os
import time
from typing import Deque, Dict

from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import Response

_WINDOW_SECONDS = 60

# Loaded once at import; tests can monkey-patch _get_limit() to override.
def _get_limit() -> int:
    try:
        return max(1, int(os.getenv("RATE_LIMIT_RPM", "10")))
    except (ValueError, TypeError):
        return 10


# Per-IP deque of POSIX timestamps (float) within the current window.
_buckets: Dict[str, Deque[float]] = {}


def _client_ip(request: Request) -> str:
    """Return the best-effort client IP, respecting X-Forwarded-For."""
    forwarded = request.headers.get("x-forwarded-for")
    if forwarded:
        return forwarded.split(",")[0].strip()
    if request.client:
        return request.client.host
    return "unknown"


class ChatRateLimitMiddleware(BaseHTTPMiddleware):
    """Rate-limit POST /api/chat/* to RATE_LIMIT_RPM requests per minute per IP."""

    async def dispatch(self, request: Request, call_next):
        if request.method != "POST" or not request.url.path.startswith("/api/chat/"):
            return await call_next(request)

        ip = _client_ip(request)
        now = time.monotonic()
        window_start = now - _WINDOW_SECONDS

        bucket = _buckets.setdefault(ip, collections.deque())

        # Evict timestamps outside the current window.
        while bucket and bucket[0] <= window_start:
            bucket.popleft()

        limit = _get_limit()
        if len(bucket) >= limit:
            # How many seconds until the oldest in-window request ages out.
            retry_after = int(_WINDOW_SECONDS - (now - bucket[0])) + 1
            body = json.dumps({"error": "rate_limit_exceeded", "retry_after": retry_after})
            return Response(
                content=body,
                status_code=429,
                media_type="application/json",
                headers={"Retry-After": str(retry_after)},
            )

        bucket.append(now)
        return await call_next(request)

